import { counts, countsOn, statusOn, useClaims } from '../claims/useClaims';
import { claimDueNow } from '../overdue/useOverdue';
import { gradeOn, holdsById, usePeople } from '../people/usePeople';
import { rateFor, sumDues, useRates } from '../rates/useRates';
import { useSettings } from '../settings/useSettings';
import { useSheetToday } from '../today/useSheetToday';
import { usePeriods } from './usePeriods';

/** Each person's due-total for each period, by person id then period name: the figures of their claims
 *  whose due-by falls in it that count by the status they had at the end of its last day (see `countsOn`) (a settled claim's frozen due, else the figure its last statement
 *  bound it to, else its live due, with its late charge while overdue), skipping those with none — the
 *  one fixed when the period was closed while it is closed or soft-closed (0.00 for a person added since).
 *  With `byStatusNow`, an open period counts each claim by the status it has now (see `counts`) instead. */
export function usePersonPeriodDueTotals(sheetId: string, byStatusNow = false): Map<number, Map<string, string>> {
  const periods = usePeriods(sheetId);
  const claims = useClaims(sheetId);
  const people = usePeople(sheetId);
  const rates = useRates(sheetId);
  const settings = useSettings(sheetId).data;
  const today = useSheetToday(sheetId).data?.today;
  const holds = holdsById(people.data, today);
  const totals = new Map<number, Map<string, string>>();
  for (const person of people.data ?? []) {
    const own = (claims.data ?? []).filter((c) => c.personId === person.id);
    const byPeriod = new Map<string, string>();
    for (const p of periods.data ?? []) {
      byPeriod.set(
        p.name,
        p.closed || p.softClosed
          ? (p.personTotals[String(person.id)] ?? '0.00')
          : sumDues(
              own
                .filter((c) => p.from <= c.dueBy && c.dueBy <= p.to && (byStatusNow ? counts(c, holds, today) : countsOn(c, p.to, holds, today)))
                .map((c) => claimDueNow(c, claims.data, rateFor(rates.data, gradeOn(person, c.date), c.date, c.added), settings, today, gradeOn(person, c.date))),
            ),
      );
    }
    totals.set(person.id, byPeriod);
  }
  return totals;
}

/** Each period's due-total, by period name: the sum of the people's due-totals for it (with `byStatusNow`,
 *  the classic figure counting each claim by its status now). */
export function usePeriodDueTotals(sheetId: string, byStatusNow = false): Map<string, string> {
  const periods = usePeriods(sheetId);
  const perPerson = [...usePersonPeriodDueTotals(sheetId, byStatusNow).values()];
  const totals = new Map<string, string>();
  for (const p of periods.data ?? []) {
    totals.set(p.name, sumDues(perPerson.map((byPeriod) => byPeriod.get(p.name) ?? '0.00')));
  }
  return totals;
}

/** Each person's carried figure for each period, by person id then period name: the figures (as the
 *  period figures count them) of their claims that count whose due-by falls in a period ending before
 *  this one starts and that were still OPEN or PENDING at the end of this period's last day, by the
 *  status log (see `statusOn`). 0.00 when nothing is carried. The one fixed when the period was closed while it is
 *  closed or soft-closed (0.00 for a person added since). */
export function usePersonPeriodCarried(sheetId: string): Map<number, Map<string, string>> {
  const periods = usePeriods(sheetId);
  const claims = useClaims(sheetId);
  const people = usePeople(sheetId);
  const rates = useRates(sheetId);
  const settings = useSettings(sheetId).data;
  const today = useSheetToday(sheetId).data?.today;
  const holds = holdsById(people.data, today);
  const carried = new Map<number, Map<string, string>>();
  for (const person of people.data ?? []) {
    const own = (claims.data ?? []).filter((c) => c.personId === person.id);
    const byPeriod = new Map<string, string>();
    for (const p of periods.data ?? []) {
      const earlier = (periods.data ?? []).filter((q) => q.to < p.from);
      byPeriod.set(
        p.name,
        p.closed || p.softClosed
          ? (p.personCarried[String(person.id)] ?? '0.00')
          : sumDues(
              own
                .filter((c) => earlier.some((q) => q.from <= c.dueBy && c.dueBy <= q.to))
                .filter((c) => {
                  const status = statusOn(c, p.to);
                  return (status === 'OPEN' || status === 'PENDING') && countsOn(c, p.to, holds, today);
                })
                .map((c) => claimDueNow(c, claims.data, rateFor(rates.data, gradeOn(person, c.date), c.date, c.added), settings, today, gradeOn(person, c.date))),
            ),
      );
    }
    carried.set(person.id, byPeriod);
  }
  return carried;
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Hold;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.settings.SettingsRepository;
import org.springframework.stereotype.Service;

/** Close an open period: fix its due-total as shown now (the dues now, late charges included, of the claims whose
 *  due-by falls in it that count by the status they had at the end of its last day, a person's open (OPEN or PENDING) claims dated
 *  within one of their holds left out unless bound by a statement, skipping those with none), so later changes to
 *  rates do not alter it; and each person's due-total for it likewise, for every person on the sheet (0.00 for one
 *  with nothing in it), and each person's carried figure for it (their claims that count whose due-by falls in a
 *  period ending before it starts and that were still OPEN or PENDING at the end of its last day, 0.00 for one with
 *  none). Writes PERIOD_CLOSED, ending auto=yes when closed by the sheet's grace days. */
@Service
public class PeriodCloser {

    private final PeriodRepository periods;
    private final ClaimRepository claims;
    private final PersonRepository people;
    private final SettingsRepository settings;
    private final Audit audit;

    public PeriodCloser(PeriodRepository periods, ClaimRepository claims, PersonRepository people,
            SettingsRepository settings, Audit audit) {
        this.periods = periods;
        this.claims = claims;
        this.people = people;
        this.settings = settings;
        this.audit = audit;
    }

    public Period close(String sheetId, String by, Period found, boolean auto) {
        return close(sheetId, by, found, auto, false);
    }

    /** Close, or soft-close, a period (open or soft-closed), fixing its figures afresh. A soft close writes
     *  PERIOD_SOFT_CLOSED instead of PERIOD_CLOSED. */
    public Period close(String sheetId, String by, Period found, boolean auto, boolean soft) {
        LocalDate from = LocalDate.parse(found.from());
        LocalDate to = LocalDate.parse(found.to());
        String today = periods.today(sheetId);
        Map<Long, List<Hold>> holds = new java.util.HashMap<>();
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        Map<Long, BigDecimal> personTotals = new LinkedHashMap<>();
        Map<Long, BigDecimal> personCarried = new LinkedHashMap<>();
        List<Period> earlier = periods.list(sheetId).stream().filter(q -> LocalDate.parse(q.to()).isBefore(from)).toList();
        for (Person p : people.list(sheetId)) {
            personTotals.put(p.id(), BigDecimal.ZERO.setScale(2));
            personCarried.put(p.id(), BigDecimal.ZERO.setScale(2));
            holds.put(p.id(), p.liveHolds(today));
        }
        Map<Long, String> statusesThen = claims.statusesOn(sheetId, to);
        for (Claim c : claims.list(sheetId)) {
            String then = statusesThen.get(c.id());
            if (!c.countsAs(then, holds.getOrDefault(c.personId(), List.of()), today)) continue;
            LocalDate on = LocalDate.parse(c.dueBy());
            boolean in = !on.isBefore(from) && !on.isAfter(to);
            boolean carried = (then.equals("OPEN") || then.equals("PENDING")) && earlier.stream()
                    .anyMatch(q -> !on.isBefore(LocalDate.parse(q.from())) && !on.isAfter(LocalDate.parse(q.to())));
            if (!in && !carried) continue;
            BigDecimal now = claims.dueNow(sheetId, c);
            if (now == null) continue;
            if (in) {
                total = total.add(now);
                personTotals.merge(c.personId(), now, BigDecimal::add);
            }
            if (carried) personCarried.merge(c.personId(), now, BigDecimal::add);
        }
        String shown = total.setScale(2).toPlainString();
        periods.close(sheetId, found.id(), total, personTotals, personCarried, soft);
        audit.record((soft ? "PERIOD_SOFT_CLOSED" : "PERIOD_CLOSED") + " sheet=" + sheetId + " by=" + by + " period=" + found.name() + " total=" + shown
                + (auto ? " auto=yes" : ""));
        return new Period(found.id(), found.name(), found.from(), found.to(), !soft, shown, personTotals.entrySet().stream().collect(Collectors.toMap(e -> Long.toString(e.getKey()),
                e -> e.getValue().setScale(2).toPlainString(), (a, b) -> a, LinkedHashMap::new)), personCarried.entrySet().stream().collect(Collectors.toMap(e -> Long.toString(e.getKey()),
                e -> e.getValue().setScale(2).toPlainString(), (a, b) -> a, LinkedHashMap::new)), soft, found.cap());
    }

    /** Close, by the sheet's grace days (none when blank), every open (not closed nor soft-closed) period whose to-date plus the grace days is
     *  before the sheet's today, in order of their to-dates. */
    public void closeLapsed(String sheetId, String by, LocalDate today) {
        Integer grace = settings.graceDays(sheetId);
        if (grace == null) return;
        List<Period> lapsed = periods.list(sheetId).stream()
                .filter(p -> !p.closed() && !p.softClosed() && LocalDate.parse(p.to()).plusDays(grace).isBefore(today))
                .sorted(Comparator.comparing(Period::to)).toList();
        for (Period p : lapsed) close(sheetId, by, p, true);
    }
}
    public String today(String sheetId) {
        List<Date> found = jdbc.queryForList("SELECT today FROM sheet WHERE id = ?", Date.class, sheetId);
        return found.isEmpty() || found.get(0) == null ? null : found.get(0).toLocalDate().toString();
    }

    /** The sheet's periods, by from-date. */
    public List<Period> list(String sheetId) {
        List<Period> periods = jdbc.query("SELECT " + COLUMNS + " FROM period WHERE sheet_id = ? ORDER BY from_date",
                ROW, sheetId);
        Map<Long, Map<String, String>> totals = new HashMap<>();
        Map<Long, Map<String, String>> carried = new HashMap<>();
        jdbc.query("SELECT period_id, person_id, total, carried FROM period_person_total WHERE sheet_id = ? ORDER BY person_id",
                rs -> {
                    totals.computeIfAbsent(rs.getLong("period_id"), k -> new LinkedHashMap<>())
                            .put(Long.toString(rs.getLong("person_id")), rs.getBigDecimal("total").setScale(2).toPlainString());
                    carried.computeIfAbsent(rs.getLong("period_id"), k -> new LinkedHashMap<>())
                            .put(Long.toString(rs.getLong("person_id")), rs.getBigDecimal("carried").setScale(2).toPlainString());
                }, sheetId);
        return periods.stream().map(p -> new Period(p.id(), p.name(), p.from(), p.to(), p.closed(), p.closedTotal(),
                totals.getOrDefault(p.id(), Map.of()), carried.getOrDefault(p.id(), Map.of()), p.softClosed(), p.cap())).toList();
    }

    /** The sheet's period of this name (exactly); null when there is none. */
    public Period find(String sheetId, String name) {
        List<Period> found = jdbc.query("SELECT " + COLUMNS + " FROM period WHERE sheet_id = ? AND name = ?", ROW,
                sheetId, name);
        return found.isEmpty() ? null : found.get(0);
    }

    /** The name of the sheet's closed period whose dates contain a date; null when none does. */
    public String closedOn(String sheetId, LocalDate on) {
        List<String> found = jdbc.queryForList("SELECT name FROM period WHERE sheet_id = ? AND closed"
                + " AND from_date <= ? AND to_date >= ?", String.class, sheetId, Date.valueOf(on), Date.valueOf(on));
        return found.isEmpty() ? null : found.get(0);
    }

    /** Close (or soft-close) a period, fixing afresh its due-total and each person's due-total and carried figure for
     *  it (by person id). */
    public void close(String sheetId, long periodId, BigDecimal total, Map<Long, BigDecimal> personTotals,
            Map<Long, BigDecimal> personCarried, boolean soft) {
        jdbc.update("DELETE FROM period_person_total WHERE period_id = ? AND sheet_id = ?", periodId, sheetId);
        jdbc.update("UPDATE period SET closed = ?, soft_closed = ?, closed_total = ? WHERE id = ? AND sheet_id = ?",
                !soft, soft, total, periodId, sheetId);
        for (Map.Entry<Long, BigDecimal> e : personTotals.entrySet()) {
            jdbc.update("INSERT INTO period_person_total (period_id, sheet_id, person_id, total, carried) VALUES (?, ?, ?, ?, ?)",
                    periodId, sheetId, e.getKey(), e.getValue(), personCarried.getOrDefault(e.getKey(), BigDecimal.ZERO));
        }
    }

    /** Reopen a closed or soft-closed period, dropping its fixed due-total and figures. */
    public void reopen(String sheetId, long periodId) {
        jdbc.update("DELETE FROM period_person_total WHERE period_id = ? AND sheet_id = ?", periodId, sheetId);
        jdbc.update("UPDATE period SET closed = FALSE, soft_closed = FALSE, closed_total = NULL WHERE id = ? AND sheet_id = ?", periodId,
                sheetId);
    }

    /** Whether the sheet has a period of this name, without regard to case. */
    public boolean named(String sheetId, String name) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM period WHERE sheet_id = ? AND name_key = LOWER(?)",
                Integer.class, sheetId, name);
        return n != null && n > 0;
    }

    /** Whether any period of the sheet shares a day with from..to (inclusive). */
    public boolean overlaps(String sheetId, LocalDate from, LocalDate to) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM period WHERE sheet_id = ?"
                + " AND from_date <= ? AND to_date >= ?", Integer.class, sheetId, Date.valueOf(to), Date.valueOf(from));
        return n != null && n > 0;
    }

    /** The sheet's period whose dates contain a date; null when none does. */

