package net.officefloor.hq.app.settings;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.history.AsOfView;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

/** Refuse any change from a screen showing the sheet as of a date, any change by a viewer of the sheet, and any change at all to an archived sheet (400, nothing written). The first step of every endpoint
 *  that changes a sheet, except the bulk ones, where a viewer's selection is simply all refused. */
public class RefuseViewer {
    public void refuse(@PathVariable("sheetId") String sheetId, ServerHttpConnection connection,
            SettingsRepository settings) throws BadRequestException {
        String by = CurrentUser.require(connection);
        AsOfView.refuse(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        if (settings.archived(id)) {
            throw new BadRequestException("the sheet is archived");
        }
        if (settings.role(id, by).equals(SettingsRepository.VIEWER)) {
            throw new BadRequestException("a viewer can change nothing");
        }
    }
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A sheet's period: its name (unique on the sheet) and its from- and to-date (yyyy-mm-dd), both
 *  inclusive, whether it is closed, the due-total fixed when it was closed (null while open), and each
 *  person's due-total for it fixed then, by person id (empty while open), and each person's carried figure for it fixed then,
 *  by person id (empty while open), and whether it is soft-closed (its figures fixed as when closed,
 *  while claims dated in it can still be changed), and its cap on each person's OPEN or PENDING claims in it (null for none). No two periods of a sheet overlap. */
export type Period = {
  id: number;
  name: string;
  from: string;
  to: string;
  closed: boolean;
  closedTotal: string | null;
  personTotals: Record<string, string>;
  personCarried: Record<string, string>;
  softClosed: boolean;
  cap: number | null;
};

export function periodsKey(sheetId: string) {
  return ['sheet', sheetId, 'periods'];
}

/** The sheet's periods, by from-date. */
export function usePeriods(sheetId: string) {
  return useQuery({
    queryKey: periodsKey(sheetId),
    queryFn: async () =>
      (await getJson<{ periods: Period[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/periods`)).periods,
  });
}

/** The fiscal year (FY<yyyy>, by the calendar year its first day falls in) a date (yyyy-mm-dd) falls in, for a
 *  fiscal year starting in a month (1 to 12). */
export function fiscalYearOf(on: string, startMonth: number): string {
  const year = Number(on.slice(0, 4));
  const month = Number(on.slice(5, 7));
  return `FY${month >= startMonth ? year : year - 1}`;
